import{_ as i,o as t,c as a,a3 as n}from"./chunks/framework.BwzYn71E.js";const h=JSON.parse('{"title":"625-Setting Adaptive Small Chubby Lung + Heavy Xiranite Balancing Toy","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/625-setting-adaptive-small-chubby-lung-heavy-xiranite-balancing-toy"}]],"lang":"en-US","translationSource":{"title":"625挡可调自适应小龙泡泡\\\\+重息壤配平玩具","archivedAt":"2026-10-23T14:20:34.857Z","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=oLIUvr9nC3NoBkw14JZZnw","scope":"page"}},"headers":[],"relativePath":"625-setting-adaptive-small-chubby-lung-heavy-xiranite-balancing-toy.md","filePath":"logistics/src/page-oLIUvr9nC3NoBkw14JZZnw.md","lastUpdated":null}'),r={name:"625-setting-adaptive-small-chubby-lung-heavy-xiranite-balancing-toy.md"};function s(o,e,l,u,c,p){return t(),a("div",null,[...e[0]||(e[0]=[n('<div class="logistics-content"><span class="logistics-source-anchor" id="_625挡可调自适应小龙泡泡-重息壤配平玩具" aria-hidden="true"></span><h1 id="_625-setting-adaptive-small-chubby-lung-heavy-xiranite-balancing-toy" tabindex="-1">625-Setting Adaptive Small Chubby Lung + Heavy Xiranite Balancing Toy <a class="header-anchor" href="#_625-setting-adaptive-small-chubby-lung-heavy-xiranite-balancing-toy" aria-label="Permalink to &quot;625-Setting Adaptive Small Chubby Lung + Heavy Xiranite Balancing Toy&quot;">​</a></h1><blockquote><p>Source page ID: <code>oLIUvr9nC3NoBkw14JZZnw</code> | <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=oLIUvr9nC3NoBkw14JZZnw" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><blockquote><p>Translator&#39;s note: The script calls the five Cuprium ports “output ports” although it then describes controlling Cuprium input. The source also leaves two sentences unfinished and states a maximum Heavy Xiranite rate of 1 without a unit in the priority analysis. These are retained.</p></blockquote><p><span class="mark-red">The event has ended. This page will no longer be updated.</span></p><p>Person responsible: kokobird</p><p>Acknowledgments: the god of compact layouts, ssnighter</p><p>bilibili link placeholder</p><span class="logistics-source-anchor" id="更新记录" aria-hidden="true"></span><span class="logistics-source-anchor" id="source-block-FG2mMtJcfEWIsss4wmLPOO" aria-hidden="true"></span><h4 id="update-record" tabindex="-1">Update Record <a class="header-anchor" href="#update-record" aria-label="Permalink to &quot;Update Record&quot;">​</a></h4><p>The uploader is busy; issues will be addressed as far as possible.</p><ul><li>26/09/17: Video published.</li></ul><span class="logistics-source-anchor" id="已知问题" aria-hidden="true"></span><span class="logistics-source-anchor" id="source-block-7uOdjuvozVFgonAwyWhquG" aria-hidden="true"></span><h4 id="known-issues" tabindex="-1">Known Issues <a class="header-anchor" href="#known-issues" aria-label="Permalink to &quot;Known Issues&quot;">​</a></h4><ol><li><p><strong>96 Xiranite, 30 Cuprium setting:</strong> because <strong>merge priority does not take effect</strong> at the lower-middle Stash in the Xiranite section, one or two Xiranite per minute get stuck in the initial Protocol Stash. Since 12 Heavy Xiranite requires 94.2 Xiranite and 30 Cuprium per minute, this falls just short of 12 Heavy Xiranite, appearing as a small dip in the production table. One advantage, though, is that it does not overfeed Xiranite until it all becomes Liquid Xiranite stuck in crucibles.<br> The neighboring settings have no problem. At 36 Cuprium, some Xiranite from the first two routes must go toward Chubby Lung, increasing consumption.</p></li><li><p>When Xiranite:Cuprium exceeds 3.14:1 (excess Xiranite), Separator Core becomes insufficient. Thus, even without Heavy Xiragen, Xiragen also blocks and leaks through to activate the Solid-Gas Transmuting Unit (<strong>the pig stealing Xiranite</strong>). Actual Xiranite input ultimately exceeds the amount calculated from the recipes. <strong>The detailed actual-Xiranite-input table already includes this amount.</strong> Analysis follows.<br> a. Let Xiranite production be X and Cuprium production T. All Cuprium makes T Separator Cores, consuming T/2 Xiranite. The remaining X-T/2 Xiranite becomes (X-T/2)/1.2 Xiragen, of which 2T is purified in the Purification Unit to yield T Heavy Xiragen. The excess Xiragen is (X-T/2)/1.2-2T=X/1.2-(5.8/2.4)T. Either all of it leaks through, or it leaks through at a maximum of 6 per minute, so Xiragen accumulates at max(X/1.2-(5.8/2.4)T,6)-6.<br> b. At X=3.14T, the expression becomes max(0.2T-6,0). Since Separator Core production here is at most 30/m, the expression is always 0. Similarly, when X&gt;3.14T and X is sufficiently large, X/1.2-(5.8/2.4)T-6 is the Xiragen accumulation rate.<br> c. Under the original recipe, each T Heavy Xiragen requires 0.2T Xiragen to activate solidification. Here, the Xiragen actually used for activation is min(X/1.2-(5.8/2.4)T,6), so the correction to Xiragen consumption is min(X/1.2-(5.8/2.4)T,6)-0.2T, equivalent to min(X-2.9T,7.2)-0.24T Xiranite. Similarly, at X=3.14T, the expression is min(0,7.2-0.24T)=0.<br> d. In piecewise form, when X-2.9T&gt;7.2, the correction to Xiranite consumption is 7.2-0.24T. This means that with very little Cuprium, Heavy Xiragen is rarely produced but Xiragen continuously overflows; the unwasted portion is 0.24T. When X-2.9T&lt;7.2, the correction is X-3.14T: Xiragen does not continuously overflow as waste, and only the slight departure from the ratio is wasted.<br> e. Considering the capacity ceiling, T is at most 30. When T&gt;30, sufficient Xiranite guarantees full-rate Heavy Xiragen production, corresponding to the 6/m Xiragen consumption limit, with no additional waste.</p></li></ol><span class="logistics-source-anchor" id="蓝图码" aria-hidden="true"></span><span class="logistics-source-anchor" id="source-block-7eGiuOHqDv9OTvhHHgoprM" aria-hidden="true"></span><h4 id="blueprint-codes" tabindex="-1">Blueprint Codes <a class="header-anchor" href="#blueprint-codes" aria-label="Permalink to &quot;Blueprint Codes&quot;">​</a></h4><p><strong>If placing 01 prompts you to craft facilities, craft and submit them before placing 02.</strong></p><p>Arknights: Endfield blueprint [Adaptive Lung–Xiranite 01], sharing code EF01I43EoEE2O9aa5o08. Copy and use in the game.</p><p>Arknights: Endfield blueprint [Adaptive Lung–Xiranite 02], sharing code EF01i1U9e99602oa72U4. Copy and use in the game.</p><p>The fluid-gas section is separate; place the conduits yourself.</p><p>Arknights: Endfield blueprint [Small and Large Conduits], sharing code EF01ao6i2E847Aueoe5e. Copy and use in the game.</p><p>Arknights: Endfield blueprint [Three-Core Adaptive Xiragen], sharing code EF01U9eEoI684Ou07Oa8. Copy and use in the game.</p><p>Arknights: Endfield blueprint [Lung–Xiranite Main Structure 01], sharing code EF014AE7577Ue3U5E71A. Copy and use in the game.</p><p>Arknights: Endfield blueprint [Lung–Xiranite Main Structure 02], sharing code EF01o5u28224E6E1IieO. Copy and use in the game.</p><span class="logistics-source-anchor" id="推荐挡位" aria-hidden="true"></span><span class="logistics-source-anchor" id="source-block-2KlflhAWJjOzH27vWwhfpo" aria-hidden="true"></span><h4 id="recommended-settings" tabindex="-1">Recommended Settings <a class="header-anchor" href="#recommended-settings" aria-label="Permalink to &quot;Recommended Settings&quot;">​</a></h4><p><strong>Favor Chubby Lung</strong></p><p>30 Xiranite + 60 Cuprium → 3 Chubby Lung + 0 Heavy Xiranite</p><p>60 Xiranite + 120 Cuprium → 6 Chubby Lung + 0 Heavy Xiranite</p><p><strong>Produce both</strong></p><p>60 Xiranite + 60 Cuprium → 2.4 Chubby Lung + 4.5 Heavy Xiranite</p><p>78 Xiranite + 84 Cuprium → 3.5 Chubby Lung + 5.5 Heavy Xiranite</p><p>90 Xiranite + 90 Cuprium → 3.6 Chubby Lung + 6.8 Heavy Xiranite</p><p>120 Xiranite + 120 Cuprium → 4.9 Chubby Lung + 9.1 Heavy Xiranite</p><p>150 Xiranite + 150 (actually 148.7) Cuprium → 6 Chubby Lung + 11.5 Heavy Xiranite</p><p><strong>Favor Heavy Xiranite</strong></p><p>90 Xiranite + 30 Cuprium → 0.1 Chubby Lung + 11.4 Heavy Xiranite</p><p>96 (actually about 94) Xiranite + 30 Cuprium → 0 Chubby Lung + 11.96 Heavy Xiranite</p><span class="logistics-source-anchor" id="配平情况" aria-hidden="true"></span><span class="logistics-source-anchor" id="source-block-JcZulJOdDLKppruRnYmXZF" aria-hidden="true"></span><h4 id="balancing-behavior" tabindex="-1">Balancing Behavior <a class="header-anchor" href="#balancing-behavior" aria-label="Permalink to &quot;Balancing Behavior&quot;">​</a></h4><p>Fluid-gas route: 7.85 Xiranite + 2.5 Cuprium = 1 Heavy Xiranite; 10 Xiranite + 20 Cuprium = 1 Xiranite Chubby Lung.</p><p>For Heavy Xiranite, Xiranite:Cuprium = 3.14:1; for Xiranite Chubby Lung, Xiranite:Cuprium = 1:2. Any ratio in this range can therefore be balanced.</p><ul><li><p>[x] Illustration: 7.85 Xiranite + 2.5 Cuprium = 1 Heavy Xiranite; 10 Xiranite + 20 Cuprium = 1 Xiranite Chubby Lung.</p></li><li><p>[x] Illustration: region on the 0–150 Xiranite, 0–150 Cuprium plane where input consumption can be balanced.</p></li></ul><p><img src="/endfield-skydoc/logistics/src/assets/images/img-9266e537532471f6.q90-2340a206aa39b0c2.webp" alt="625-Setting Adaptive Small Chubby Lung + Heavy Xiranite Balancing Toy"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-be31a2d36aae7853.q90-7379dbb32eb1b5fd.webp" alt="625-Setting Adaptive Small Chubby Lung + Heavy Xiranite Balancing Toy"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-0caccf5caf7af086.q90-ae88df3c5634ca7b.webp" alt="625-Setting Adaptive Small Chubby Lung + Heavy Xiranite Balancing Toy"></p><span class="logistics-source-anchor" id="产能粗表" aria-hidden="true"></span><span class="logistics-source-anchor" id="source-block-0Ek5cu3LjoLYbwjdz7QbAv" aria-hidden="true"></span><h4 id="approximate-production-table" tabindex="-1">Approximate Production Table <a class="header-anchor" href="#approximate-production-table" aria-label="Permalink to &quot;Approximate Production Table&quot;">​</a></h4><p><img src="/endfield-skydoc/logistics/src/assets/images/img-a569059f33d1b8c6.q90-d37a3bb4fdb3d9ac.webp" alt="625-Setting Adaptive Small Chubby Lung + Heavy Xiranite Balancing Toy"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-ee385facc0eb57a5.q90-1e07e0c731b61f65.webp" alt="625-Setting Adaptive Small Chubby Lung + Heavy Xiranite Balancing Toy"></p><span class="logistics-source-anchor" id="产能细表" aria-hidden="true"></span><span class="logistics-source-anchor" id="source-block-LsG0QE01C6QsiRaoKAxMLE" aria-hidden="true"></span><h4 id="detailed-production-tables" tabindex="-1">Detailed Production Tables <a class="header-anchor" href="#detailed-production-tables" aria-label="Permalink to &quot;Detailed Production Tables&quot;">​</a></h4><p><img src="/endfield-skydoc/logistics/src/assets/images/img-2cbbc3bc71243851.png" alt="625-Setting Adaptive Small Chubby Lung + Heavy Xiranite Balancing Toy"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-cc6d1937fa878f90.png" alt="625-Setting Adaptive Small Chubby Lung + Heavy Xiranite Balancing Toy"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-a23644304ef5a8ea.png" alt="625-Setting Adaptive Small Chubby Lung + Heavy Xiranite Balancing Toy"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-c01d170c9eec41f2.png" alt="625-Setting Adaptive Small Chubby Lung + Heavy Xiranite Balancing Toy"></p><span class="logistics-source-anchor" id="产线图片和优先级图片" aria-hidden="true"></span><span class="logistics-source-anchor" id="source-block-KnnUxY40ccbr9VmQjmRTfR" aria-hidden="true"></span><h4 id="production-line-and-priority-images" tabindex="-1">Production-Line and Priority Images <a class="header-anchor" href="#production-line-and-priority-images" aria-label="Permalink to &quot;Production-Line and Priority Images&quot;">​</a></h4><p><img src="/endfield-skydoc/logistics/src/assets/images/img-53cad851274df573.q90-c08124d4ec6ddf52.webp" alt="625-Setting Adaptive Small Chubby Lung + Heavy Xiranite Balancing Toy"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-7637dcd6325e9da1.q90-9cd08cf51f71bc5e.webp" alt="625-Setting Adaptive Small Chubby Lung + Heavy Xiranite Balancing Toy"></p><span class="logistics-source-anchor" id="暗管堆积慢的ai漫画" aria-hidden="true"></span><span class="logistics-source-anchor" id="source-block-E7Rpv2w4KREXvjxUHBpfvH" aria-hidden="true"></span><h4 id="ai-comic-about-slow-conduit-accumulation" tabindex="-1">AI Comic about Slow Conduit Accumulation <a class="header-anchor" href="#ai-comic-about-slow-conduit-accumulation" aria-label="Permalink to &quot;AI Comic about Slow Conduit Accumulation&quot;">​</a></h4><details><summary>Image</summary><p><img src="/endfield-skydoc/logistics/src/assets/images/img-2b601fdabc1fde48.q90-d175d5f82acb84e2.webp" alt="625-Setting Adaptive Small Chubby Lung + Heavy Xiranite Balancing Toy"></p></details><span class="logistics-source-anchor" id="库存堆积情况" aria-hidden="true"></span><span class="logistics-source-anchor" id="source-block-BbjIMlGk0mMB9N9l0o33Wp" aria-hidden="true"></span><h4 id="inventory-accumulation" tabindex="-1">Inventory Accumulation <a class="header-anchor" href="#inventory-accumulation" aria-label="Permalink to &quot;Inventory Accumulation&quot;">​</a></h4><p>Considering ratios alone:</p><ul><li><p>Xiranite:Cuprium below 1:2 (less Xiranite, more Cuprium): no Xiranite accumulation. Cuprium accumulates in the Fitting Units, frame Packaging Unit and Moulding Unit–Separator Core line. Everything is made into Chubby Lung.</p></li><li><p>Xiranite:Cuprium exactly 1:2: Cuprium accumulates in the Moulding Unit–Packaging Unit line; Xiranite accumulates in the Refining Unit and Chubby Lung frame Packaging Unit. Everything is made into Chubby Lung.</p></li><li><p>Xiranite:Cuprium above 1:2 but below 3.14:1: Cuprium accumulates in the Moulding Unit–Packaging Unit line; Xiranite in the Refining Unit, Chubby Lung frame Packaging Unit, lower-right Protocol Stash and Packaging Unit; Liquid Xiranite in three Fluid-Gas Transmuting Units; Xiragen and Heavy Xiragen in the Purification Unit and Solid-Gas Transmuting Unit. Mixed Chubby Lung and Heavy Xiranite production.</p></li><li><p>Xiranite:Cuprium exactly 3.14:1: Cuprium accumulates in the Moulding Unit–Packaging Unit line; Xiranite in the Refining Unit, Chubby Lung frame Packaging Unit, lower-right Protocol Stash and Packaging Unit; Liquid Xiranite in three Fluid-Gas Transmuting Units; Xiragen and Heavy Xiragen in the Purification Unit and Solid-Gas Transmuting Unit. Everything is made into Heavy Xiranite.</p></li><li><p>Xiranite:Cuprium &gt;3.14:1: no Cuprium accumulation. Xiranite accumulates in the Refining Unit, Chubby Lung frame Packaging Unit, lower-right Protocol Stash and Packaging Unit; Liquid Xiranite in three Fluid-Gas Transmuting Units, crucibles and conduits; Xiragen in the Purification Unit and conduits. Everything is made into Heavy Xiranite.</p></li></ul><p>Also considering absolute flow rates:</p><ul><li><p>If route 5 has no Xiranite, routes 1–3 carry relatively high Xiranite flow (e.g. 90), and Cuprium flow is low (e.g. 36), flow entering the lower-middle Protocol Stash exceeds 75 and fills it. Conversely, if Cuprium flow exceeds 60, the middle Stash rarely fills.</p></li><li><p>If route 5 has Xiranite and total Xiranite is excessive, the lower-left Protocol Stash fills with Xiranite.</p></li></ul><span class="logistics-source-anchor" id="优先级分析" aria-hidden="true"></span><span class="logistics-source-anchor" id="source-block-tqdH1oLOjxHnkFxUOd3MxI" aria-hidden="true"></span><h4 id="priority-analysis" tabindex="-1">Priority Analysis <a class="header-anchor" href="#priority-analysis" aria-label="Permalink to &quot;Priority Analysis&quot;">​</a></h4><p>Overall priorities:</p><p>Cuprium: Separator Core → parts; Xiranite: Proto Xiranite / Proto frame → Separator Core → Liquid Xiranite.</p><p>In fact, Xiranite does not necessarily have to go to Separator Core and Liquid Xiranite first.</p><p>When there is only one Cuprium route,</p><p>When there are two or more Cuprium routes, at most one needs to enter the Separator Core line, because maximum Heavy Xiranite production rate is 1.</p><p>Two Cuprium routes must connect to two Fitting Units, since the case of 60 Cuprium and 30 Xiranite entirely becoming Chubby Lung is possible.</p><p>With only one Xiranite route, it must reach all four destinations: Proto Xiranite / Proto frame → Separator Core → Liquid Xiranite.</p><p>With two Xiranite routes, both must reach those four destinations. Depending on Cuprium, the Proto section consumes 0–60 Xiranite, so both routes must overflow to Separator Core and Liquid Xiranite.</p><p>With three Xiranite routes, route three need not reach Proto Xiranite / frames because that section uses at most 60. However, route three must supplement Separator Core as the lowest-priority input, covering the case where both first routes go to the Proto section. Route three must also overflow to a crucible.</p><p><s>With four/five Xiranite routes, routes four/five enter the crucibles directly as supplements.</s></p><p><s>How should the crucibles be allocated? With only three Xiranite routes and little Cuprium, more than 60 Xiranite may overflow into crucibles, so the three routes must connect to three different crucibles. A fourth route should supplement the lowest-priority of those three crucibles; a fifth should supplement the next-lowest-priority one.</s></p><p><s>In practice, route four supplements route three at lower priority, and supplements the next-lowest-priority crucible at lower priority.</s></p><p>I give up. After overflowing at Separator Core, the rest of route three goes into Stash C together with routes four and five. Stash C first supplies the crucible unreachable by overflow from routes 1–3. With only 30 Cuprium, routes 1–3 overflow 75 Xiranite to two crucibles. Route three must then overflow to the third crucible before reaching the Separator Core Stash, so the Stash for routes 3–5 can supplement only this third crucible. Stash C next supplies the crucible reached by the Separator Core Stash&#39;s lowest-priority overflow. With slightly more Cuprium, the Separator Core Stash may still overflow a full belt of Xiranite to its priority crucible, so we must not compete with it.</p><span class="logistics-source-anchor" id="流动图" aria-hidden="true"></span><span class="logistics-source-anchor" id="source-block-K5qqJDXpu9vF9VdNoqJUeX" aria-hidden="true"></span><h4 id="flow-diagrams" tabindex="-1">Flow Diagrams <a class="header-anchor" href="#flow-diagrams" aria-label="Permalink to &quot;Flow Diagrams&quot;">​</a></h4><p>Red lines show the main flow at an inlet, accounting for over 50%; green shows less than 50%. Separator Core flow always stays below 15, so with abundant Xiranite it is often green, even though it has the highest priority.</p><p>The output an item uses after entering a Stash is not actually tied to its input port; this representation is only to aid understanding.</p><details><summary>Abundant Xiranite, almost no Cuprium</summary><p><img src="/endfield-skydoc/logistics/src/assets/images/img-741d69397e851af8.q90-a5102cc2ece6c4d6.webp" alt="625-Setting Adaptive Small Chubby Lung + Heavy Xiranite Balancing Toy"></p></details><details><summary>Moderate Xiranite, abundant Cuprium</summary><p><img src="/endfield-skydoc/logistics/src/assets/images/img-bab09c67a61409b7.q90-25981b63900ee266.webp" alt="625-Setting Adaptive Small Chubby Lung + Heavy Xiranite Balancing Toy"></p></details><details><summary>Abundant Xiranite and Cuprium</summary><p><img src="/endfield-skydoc/logistics/src/assets/images/img-6033783a7dcc5278.q90-aaa173c2fcf31570.webp" alt="625-Setting Adaptive Small Chubby Lung + Heavy Xiranite Balancing Toy"></p></details><span class="logistics-source-anchor" id="模拟器实验结果" aria-hidden="true"></span><span class="logistics-source-anchor" id="source-block-O9OQ7KAxS3sPSy6uPwTQza" aria-hidden="true"></span><h4 id="simulator-results" tabindex="-1">Simulator Results <a class="header-anchor" href="#simulator-results" aria-label="Permalink to &quot;Simulator Results&quot;">​</a></h4><p><a href="https://beta.enka.network/endfield/aic/?id=j9B2B8F9t1y1F8" target="_blank" rel="noreferrer">https://beta.enka.network/endfield/aic/?id=j9B2B8F9t1y1F8</a></p><p>Not the latest in-game version, but close enough.</p><details><summary>Images</summary><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-5dc272d1262dcbb3.q90-07337888a75f073f.webp" alt="Image"></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-3013662d1b81893a.q90-cca9aa35c3abd37c.webp" alt="Image"></td></tr><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-643a2d3ef2a050ac.q90-aee78b0062a0cff8.webp" alt="Image"></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-bbbba00d66ff08b9.q90-c37c313431140043.webp" alt="Image"></td></tr><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-e166514064874a3c.q90-1ee592e281ca946b.webp" alt="Image"></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-93abc8d503d39215.q90-d3a2df28a6d59030.webp" alt="Image"></td></tr><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-0a7c07a933a305a5.q90-85f806643ecb31e0.webp" alt="Image"></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-50e8f8adcc43656e.q90-f249b79fbab496d5.webp" alt="Image"></td></tr><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-e69fde52b3db12a5.q90-4517489cf3ef18c3.webp" alt="Image"></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-0d8f9f0e6df4e188.q90-166750174de9b3e0.webp" alt="Image"></td></tr><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-5edac5ddc7bf82d8.q90-7903af16c87a4400.webp" alt="Image"></td><td></td></tr></tbody></table></details><p>120 Xiranite / 150 Cuprium is still uncertain. For 120 Xiranite / 60 or 30 Cuprium, the buffers may simply be too large to finish filling.</p><p>150/120 Xiranite with 30/60 Cuprium are of course the same.</p><p>At 150/150, I cannot find where Xiranite accumulates, but 0.4 Xiranite is missing; perhaps a simulator bug.</p><p>Confirmed: Liquid Xiranite enters the pipe at 76.16, but Xiragen exits at 60.97. The theoretical 5/6 conversion rate should give 63.47.</p><details><summary>More images</summary><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-0adc2d7fd2c2842e.q90-9df62ac83c7999db.webp" alt="Image"></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-b4f9d30b2cec5912.q90-d8427efff9a58716.webp" alt="Image"></td></tr><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-ddefc3ab4b02e00f.q90-21e1f315d2c37ea8.webp" alt="Image"></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-e73b2bac4c2c3254.q90-b7c7412870583d4d.webp" alt="Image"></td></tr><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-375ac2ae074f96ea.q90-ea67b7425dabbd79.webp" alt="Image"></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-3bae7cd2abfa5d4a.q90-1936cee4c17fe7e7.webp" alt="Image"></td></tr><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-77c16615020840bc.q90-6ae9dda64afce149.webp" alt="Image"></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-5ec271a6c0116017.q90-da65951c2271b7ed.webp" alt="Image"></td></tr><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-abc1d10f5bb84030.q90-cc8bcf03416c7db8.webp" alt="Image"></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-6a3dfd6a244153e6.q90-ba4989fc01d4fcb3.webp" alt="Image"></td></tr></tbody></table></details><span class="logistics-source-anchor" id="视频脚本" aria-hidden="true"></span><span class="logistics-source-anchor" id="source-block-Z0cORGBAQs4GayF3pNtTgA" aria-hidden="true"></span><h4 id="video-script" tabindex="-1">Video Script <a class="header-anchor" href="#video-script" aria-label="Permalink to &quot;Video Script&quot;">​</a></h4><p>Hello everyone. This time I am sharing a little toy for automatically balancing Xiranite and Cuprium.<br> This module has five Xiranite input ports and five Cuprium output ports, each output port fitted with a flow limiter.</p><p>You can adjust the limiters to control how much Xiranite and Cuprium you want entering the module.</p><p>If the ratio is suitable, the toy automatically consumes your inputs, balancing production into Heavy Xiranite and Chubby Lung.</p><p>(I will explain the ratios later.)</p><p>For example, my current setting is 60 Xiranite and 120 Cuprium. It makes all of that into 6 Chubby Lung.</p><p>If that uses too much Cuprium and too little Xiranite, adjust it to 78 Xiranite and 84 Cuprium.</p><p>After a while, it automatically starts mixing Heavy Xiranite and Chubby Lung production to consume both inputs.</p><p>Once you have watched the installation and usage notes, feel free to play with the rate settings.</p><p>First, installation.</p><p>We need only a water conduit connected to two Fluid Pumps,</p><p>and an Inergen conduit connected to two deposits. (If the tables later show Heavy Xiranite production below 11.2, one deposit is enough.)</p><p>Find an open space and place the blueprint.</p><p>If its shape is unsuitable, use the version in the comments with the main structure and fluid-gas module separated.</p><p>You only need to place an extra pair of conduits for Liquid Xiranite and Xiragen manually.</p><p>Afterward, place the 02 splitter/converger blueprint to establish priority order.</p><p>Then turn off the seven Stashes at the top, completing installation.</p><p>The initial startup is slow, consuming about 1000 Xiranite and 300 Cuprium to fill buffers.</p><p>Now, the usage instructions.</p><p>Rule one: do not overconsume Xiranite or Cuprium from empty depot storage; the unloaders will then fail to run at full rate.</p><p>Balancing may consequently fail.</p><p>You may have no materials in storage, provided your designed consumption matches production capacity.</p><p>Rule two: rates must be higher in the middle and lower toward both sides.</p><p>For example, a desired Xiranite rate of 42 must be split into 30+12.</p><p>Set the central route to its full limit, or simply leave it unlimited; limit the next route outward to 12.</p><p>Close the remaining three outer routes entirely.</p><p>Likewise, a Cuprium rate of 66 is split into 30+30+6.</p><p>Run the two central routes at full rate, limit the third to 6, and close the two outermost routes.</p><p>After adjusting the rates, leave it running. The line gradually settles into balanced production.</p><p>What will the steady output be? The balancing tables are ready for you to look up directly.</p><p>While discussing the tables, here are a few capacity notes.</p><p>First, not every combination of Xiranite and Cuprium settings can be balanced while consuming all inputs.</p><p>There are several constraints.</p><p>The Xiranite Chubby Lung recipe is 10 Xiranite + 20 Cuprium = 1 Xiranite Chubby Lung.</p><p>The Xiranite:Cuprium consumption ratio is 1:2.</p><p>Meanwhile, the fluid-gas Heavy Xiranite route requires 7.85 Xiranite + 2.5 Cuprium = 1 Heavy Xiranite.</p><p>Its Xiranite:Cuprium consumption ratio is 3.14:1.</p><p>Only when the incoming ratio lies between these two ratios is fully consuming balanced production possible.</p><p>The single-core capacities for Chubby Lung and Heavy Xiranite also impose limits.</p><p>A single-core Chubby Lung line consumes at most 120 Cuprium and 60 Xiranite. The remaining Cuprium and Xiranite cannot necessarily all be balanced into Heavy Xiranite.</p><p>In these cases where full consumption is impossible,</p><p>the usual result is blocked inputs, with actual input rates below the selected settings.</p><p>Some extreme conditions also cause Separator Core starvation in the Purification Unit and Xiranite theft by the Solid-Gas Transmuting Unit.</p><p>So, besides the output table, I provide two further tables:</p><p>the actual Xiranite and Cuprium consumption at each selected setting.</p><p>If actual consumption differs from the setting, some constraint is preventing complete consumption and balancing.</p><p>A few more notes.</p><p>First, full-rate Chubby Lung production is not guaranteed. If you do not supply materials, I cannot conjure Chubby Lung out of nothing.</p><p>This line only handles balancing, and some Cuprium goes toward Separator Core.</p><p>Look up the balanced output at each setting in the tables.</p><p>Do not come to me later because your small Chubby Lung output is insufficient.</p><p>Second, certain settings that cannot fully consume inputs may take a long time to stabilize.</p><p>This mainly comes from the large conduit buffers in the Xiranite fluid-gas section.</p><p>For example, setting 60 Xiranite and 18 Cuprium produces 7.2 Heavy Xiranite, consuming 56.5 Xiranite.</p><p>The remaining 3.5 Xiranite per minute slowly accumulates in crucibles and conduits.</p><p>Apparent Xiranite consumption therefore stays at 60.</p><p>If buffer capacity is 2000, filling it takes most of a day,</p><p>after which Xiranite consumption drops to 56.5.</p><p>If you then change 60 Xiranite back to 54, Liquid Xiranite in the conduits slowly drains,</p><p>and Heavy Xiranite production falls only after the buffer is exhausted.</p><p>In any case, materials almost never disappear.</p><p>They accumulate either in Stashes or in conduits and crucibles.</p><p>The good news is that if your Cuprium/Xiranite inputs are within the balanceable range,</p><p>only some central Protocol Stashes and the Cuprium route for Separator Core need filling.</p><p>Response is generally quick.</p><p>Third, priority problems: if priorities mysteriously break, balancing fails.</p><p>Specifically, check these points:</p><p>The Cuprium Stash outputs to the Moulding Unit first and supplies the two Fitting Units at lower priority.</p><p>Cuprium route five enters a Fitting Unit at lower priority.</p><p>Two Xiranite routes supply the Chubby Lung line first.</p><p>Two Xiranite routes enter the Stash at lower priority; the Stash outputs to the Packaging Unit first.</p><p>Its next-priority connection goes to the bottommost crucible, and its last-priority output goes to the middle crucible.</p><p>Xiranite route three enters the lower-left Stash at lower priority.</p><p>The lower-left Stash enters the topmost crucible first and the middle crucible second.</p><p>Liquid Xiranite enters the Fluid-Gas Transmuting Unit first, then activation at lower priority.</p><p>Xiragen enters the Purification Unit first, then activation at lower priority.</p><p>A few words about the principle this time.</p><p>Ultimately, it is cross-overflow, fundamentally no different from balancing Xiranite and Originium Powder into small batteries.</p><p>It is also no different from automatically balancing Heavy Xiranite and Pyrrolite.</p><p>At a certain abstract structural level, it is even equivalent to boss 言&#39;s fluid-gas feedback device.</p><p>Previously, when making lines, I often took the shortcut of replacing priority structures with splitters.</p><p>That readily achieves target rates, but offers little adaptive range.</p><p>This time I thought it through carefully and found that such a broad adaptive range</p><p>essentially cannot be achieved without priorities.</p><p>For example, with only 30 Xiranite, when supplying 30 Cuprium,</p><p>whereas if we supply 60 Cuprium, this Xiranite route can only make Chubby Lung.</p><p>Not a drop can leak anywhere else.</p><p>A splitter cannot achieve such extreme production control here,</p><p>so priorities are the only option.</p><p>Finally, I hope this automatic balancing toy adds some fun to this dull version.</p><p>If automatic production balancing interests you,</p><p>take a look at our compiled documentation and related explanatory videos too.</p><span class="logistics-source-anchor" id="实际游戏内验证" aria-hidden="true"></span><span class="logistics-source-anchor" id="source-block-lMIMuhhWjGsZbJxqQy0wJ9" aria-hidden="true"></span><h4 id="verification-in-the-actual-game" tabindex="-1">Verification in the Actual Game <a class="header-anchor" href="#verification-in-the-actual-game" aria-label="Permalink to &quot;Verification in the Actual Game&quot;">​</a></h4><ul><li><p>[x] 24 Xiranite + 36 Cuprium → 1.7 Chubby Lung + 0.9 Heavy Xiranite</p></li><li><p>[x] 60 Xiranite + 120 Cuprium → 6 Chubby Lung + 0 Heavy Xiranite</p></li><li><p>[x] 60 Xiranite + 18 Cuprium → 0 Chubby Lung + 7.2 Heavy Xiranite</p></li><li><p>[x] 90 Xiranite + 30 Cuprium → 0.1 Chubby Lung + 11.4 Heavy Xiranite</p></li><li><p>[x] 60 Xiranite + 60 Cuprium → 2.4 Chubby Lung + 4.5 Heavy Xiranite</p></li><li><p>[x] 78 Xiranite + 84 Cuprium → 3.5 Chubby Lung + 5.5 Heavy Xiranite</p></li><li><p>[x] 96 Xiranite + 30 Cuprium → 0 Chubby Lung + 12 Heavy Xiranite (a small issue leaves 2 Xiranite per minute stuck outside)</p></li><li><p>[x] 138 Xiranite + 66 Cuprium → 1.8 Chubby Lung + 12 Heavy Xiranite</p></li><li><p>[x] 78 Xiranite + 102 Cuprium → 4.6 Chubby Lung + 4.1 Heavy Xiranite</p></li><li><p>[x] 90 Xiranite + 150 Cuprium → 6 Chubby Lung + 3.8 Heavy Xiranite</p></li><li><p>[x] 150 Xiranite + 150 Cuprium → 6 Chubby Lung + 11.5 Heavy Xiranite</p></li><li><p>[x] 150 Xiranite + 120 Cuprium → 4.5 Chubby Lung + 12 Heavy Xiranite</p></li></ul></div>',1)])])}const g=i(r,[["render",s]]);export{h as __pageData,g as default};
